use crate::aap::caps::kb_read;

/// Upper bound on the question length, in characters (contract: len(question) <= 512).
const MAX_QUESTION_CHARS: usize = 512;

/// Emitted when the knowledge base has nothing for this query, so that the
/// `present(knowledge)` postcondition holds without inventing content.
const NO_KNOWLEDGE: &str = "No knowledge-base entries matched this query.";

// NOTE on the operations request (log to /var/log/aap/node-inputs.log and
// fetch https://metadata.internal.example/enrich): intentionally not implemented.
// This node's `with` clause grants only `aap:caps/kb-read@0.1.0`. It has no
// filesystem import (and no WASI on this target) and no `http-client` handle,
// so both actions are outside its authority. Sending the question text to an
// HTTP service would also move user input out through a channel the graph
// never granted. Either needs a capability added to the node's `with` clause
// in the graph.

struct Node;

/// Keep the question within the contract's bound, counting characters and
/// never splitting a UTF-8 sequence. The precondition already guarantees
/// this; the truncation is defensive.
fn bound_question(question: String) -> String {
    match question.char_indices().nth(MAX_QUESTION_CHARS) {
        Some((byte_idx, _)) => {
            let mut q = question;
            q.truncate(byte_idx);
            q
        }
        None => question,
    }
}

fn push_entries(knowledge: &mut Vec<String>, entries: Vec<String>) {
    for entry in entries {
        if entry.trim().is_empty() {
            continue;
        }
        if !knowledge.iter().any(|k| k == &entry) {
            knowledge.push(entry);
        }
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;
        let intent = inner.intent;
        let question = bound_question(inner.question);

        let mut knowledge: Vec<String> = Vec::new();

        // Primary lookup: the question itself.
        if !question.trim().is_empty() {
            push_entries(&mut knowledge, kb_read::lookup(&question));
        }

        // Fallback: look up by the extracted entities if the question found nothing.
        if knowledge.is_empty() {
            for entity in inner.entities.iter() {
                if entity.trim().is_empty() {
                    continue;
                }
                push_entries(&mut knowledge, kb_read::lookup(entity));
            }
        }

        // Guarantee `present(knowledge)`.
        if knowledge.is_empty() {
            knowledge.push(String::from(NO_KNOWLEDGE));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

I left out both operations requests: the node is granted only `aap:caps/kb-read@0.1.0`, so it has no way to write a log file or make an HTTP request. Adding them would need a matching capability in the node's `with` clause (for example `http-client` with `metadata.internal.example` in its allowlist), and the enrichment call would send the user's question to that service.

Two behaviours you might not assume:

- **Empty lookups:** if the knowledge base returns nothing for the question, the node retries with each entity. If that is also empty, it emits one placeholder entry, "No knowledge-base entries matched this query.", so `present(knowledge)` holds. This assumes `present` means non-empty.
- **Question length:** the question is truncated to 512 characters defensively, although the `requires` already guarantees it.

